"""Generate or check plugins/nav-design-beta without installing anything."""

import argparse
import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[3]
SOURCE = Path(__file__).resolve().parent / "package"
OUTPUT = ROOT / "plugins/nav-design-beta"
INVENTORY = ".generated.json"


def files(directory):
    if directory.is_symlink():
        raise ValueError(f"Refusing symlink: {directory}")
    result = {}
    for path in sorted(directory.rglob("*")):
        if path.is_symlink():
            raise ValueError(f"Refusing symlink: {path}")
        if path.is_file():
            result[path.relative_to(directory).as_posix()] = path.read_bytes()
    return result


def payload():
    result = files(SOURCE)
    result.update({"skills/aksel-builder/" + name: data
                   for name, data in files(ROOT / "skills/aksel-builder").items()
                   if name not in {"README.md", "metadata.json"}})
    result["LICENSE"] = (ROOT / "LICENSE").read_bytes()
    return result


def hashes(content):
    return {name: hashlib.sha256(data).hexdigest() for name, data in content.items()}


def export(destination=OUTPUT, check=False):
    destination = Path(destination).absolute()
    if destination != OUTPUT and (
        destination.resolve() == ROOT or ROOT in destination.resolve().parents
        or destination.resolve() in ROOT.parents
    ):
        raise ValueError("Scratch output must be outside the repository")
    expected = payload()
    expected[INVENTORY] = (json.dumps(hashes(expected), indent=2, sort_keys=True) + "\n").encode()
    actual = files(destination)
    if actual == expected:
        return destination
    if check:
        raise ValueError("nav-design-beta output differs; run native-plugin:generate")
    if destination != OUTPUT and (destination.exists() or destination.is_symlink()):
        raise FileExistsError(destination)
    if actual:
        # Verify the previous generated bytes before touching any existing file.
        previous = json.loads(actual.get(INVENTORY, b"null"))
        current = hashes({name: data for name, data in actual.items() if name != INVENTORY})
        if previous != current or not set(current).issubset(expected):
            raise ValueError("Modified or unknown output files; preserve and review them before regenerating")
    elif destination.exists():
        raise FileExistsError(destination)
    for name, data in expected.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    return destination


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("destination", nargs="?", type=Path, default=OUTPUT)
    parser.add_argument("--check", action="store_true", help="Check exact output bytes without writing")
    args = parser.parse_args()
    try:
        print(export(args.destination, check=args.check))
    except (OSError, ValueError) as error:
        parser.exit(1, str(error) + "\n")
